{
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, sans-serif;
    background-color: #fffaf3;
    color: #333;
    line-height: 1.6;
}

/* Navigation Bar */
header {
    background-color: #2b2118;
    color: white;
    padding: 18px 8%;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    color: #ffb347;
    font-size: 28px;
    font-weight: bold;
}

nav a {
    color: white;
    text-decoration: none;
    margin-left: 25px;
    transition: color 0.3s;
}

nav a:hover {
    color: #ffb347;
}

/* Hero Section */
.hero {
    min-height: 450px;
    background: linear-gradient(
        rgba(0, 0, 0, 0.55),
        rgba(0, 0, 0, 0.55)
    ), url("restaurant.jpg") center/cover no-repeat;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    color: white;
    padding: 40px 20px;
}

.hero h1 {
    font-size: clamp(32px, 5vw, 55px);
    margin-bottom: 15px;
}

.hero p {
    font-size: 18px;
    margin-bottom: 25px;
}

.btn {
    display: inline-block;
    background-color: #e85d04;
    color: white;
    padding: 12px 28px;
    border-radius: 6px;
    text-decoration: none;
    transition: background 0.3s;
}

.btn:hover {
    background-color: #c74700;
}

/* Menu Section */
.menu {
    padding: 60px 8%;
    text-align: center;
}

.menu h2 {
    font-size: 34px;
    margin-bottom: 30px;
    color: #8b3e16;
}

.menu-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 25px;
}

.menu-item {
    background-color: white;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
    transition: transform 0.3s;
}

.menu-item:hover {
    transform: translateY(-7px);
}

.menu-item img {
    width: 100%;
    height: 200px;
    object-fit: cover;
}

.menu-item h3 {
    margin: 15px 10px 5px;
}

.menu-item p {
    padding: 0 15px;
    color: #666;
}

.price {
    display: block;
    color: #e85d04;
    font-size: 20px;
    font-weight: bold;
    padding: 10px 0 20px;
}

/* About Section */
.about {
    padding: 55px 8%;
    background-color: #f5e6d3;
    text-align: center;
}

.about h2 {
    color: #8b3e16;
    margin-bottom: 15px;
    font-size: 32px;
}

/* Contact Section */
.contact {
    text-align: center;
    padding: 50px 20px;
}

.contact h2 {
    color: #8b3e16;
    margin-bottom: 15px;
}

/* Footer */
footer {
    background-color: #2b2118;
    color: white;
    text-align: center;
    padding: 20px;
}

/* Mobile Responsive */
@media (max-width: 600px) {
    header {
        flex-direction: column;
        gap: 12px;
    }

    nav {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        gap: 12px;
    }

    nav a {
        margin-left: 0;
    }

    .hero {
        min-height: 350px;
    }

    .menu {
        padding: 40px 5%;
    }
}
